15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials", expression = "java(initials(owner))")
24	    @Mapping(target = "locality", expression = "java(locality(owner))")
25	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
26	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
27	    @Mapping(target = "membershipLevel",
28	            expression = "java(org.springframework.samples.petclinic.mapper.OwnerMapper.membershipLevel(owner))")
29	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
30	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
31	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
32	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
33	    OwnerDto toOwnerDto(Owner owner);
34	
35	    /**
36	     * The owner's stored E.164 {@code telephone} formatted for humans: the '+' country code, a space,
37	     * then the national digits grouped in threes (e.g. {@code '+61 412 345 678'}). Null when no
38	     * telephone is recorded.
39	     */
40	    default String telephoneDisplay(Owner owner) {
41	        return org.springframework.samples.petclinic.rest.function.owner.OwnerTelephone.toDisplay(
42	                owner.getTelephone());
43	    }
44	
45	    /**
46	     * The owner's age band, computed from {@code birthDate} against {@code registrationDate}:
47	     * {@code MINOR} (under 18), {@code ADULT} (18-64) or {@code SENIOR} (65+). Null when no
48	     * birth date is recorded.
49	     */
50	    default String ageBand(Owner owner) {
51	        if (owner.getBirthDate() == null) {
52	            return null;
53	        }
54	        java.time.LocalDate reference = owner.getRegistrationDate() != null
55	                ? owner.getRegistrationDate() : java.time.LocalDate.now();
56	        int age = java.time.Period.between(owner.getBirthDate(), reference).getYears();
57	        if (age < 18) {
58	            return "MINOR";
59	        }
60	        if (age < 65) {
61	            return "ADULT";
62	        }
63	        return "SENIOR";
64	    }
65	
66	    /**
67	     * The owner's derived {@code identityKey} = normalizedTelephone + '|' + (email or empty) + '|' +
68	     * householdId, the single key all duplicate detection is expressed through.
69	     */
70	    default String identityKey(Owner owner) {
71	        return org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(
72	                owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
73	    }
74	
75	    /**
76	     * The owner's preferred contact channel: {@code EMAIL} when an email is present, otherwise
77	     * {@code PHONE}.
78	     */
79	    default String contactPreference(Owner owner) {
80	        return owner.getEmail() != null && !owner.getEmail().isBlank() ? "EMAIL" : "PHONE";
81	    }
82	
83	    default String initials(Owner owner) {
84	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
85	                + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
86	    }
87	
88	    /**
89	     * The owner's locality (region), read from the REGION component of the customerCode
90	     * ({@code <REGION>-<HASH8>}); see
91	     * {@link org.springframework.samples.petclinic.rest.function.owner.OwnerRegion#regionOf}.
92	     */
93	    default String locality(Owner owner) {
94	        return org.springframework.samples.petclinic.rest.function.owner.OwnerRegion.regionOf(
95	                owner.getCustomerCode());
96	    }
97	
98	    /**
99	     * A single Luhn check digit (0-9) computed over the digits of the owner's {@code customerCode}.
100	     * Null when the customer code is absent.
101	     */
102	    default Integer checkDigit(Owner owner) {
103	        if (owner.getCustomerCode() == null) {
104	            return null;
105	        }
106	        String code = owner.getCustomerCode();
107	        int sum = 0;
108	        boolean dbl = true;
109	        for (int i = code.length() - 1; i >= 0; i--) {
110	            char c = code.charAt(i);
111	            if (c < '0' || c > '9') {
112	                continue;
113	            }
114	            int d = c - '0';
115	            if (dbl) {
116	                d *= 2;
117	                if (d > 9) {
118	                    d -= 9;
119	                }
120	            }
121	            sum += d;
122	            dbl = !dbl;
123	        }
124	        return (10 - (sum % 10)) % 10;
125	    }
126	
127	    /**
128	     * The owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the last two
129	     * digits of the registrationDate year (e.g. {@code NSW-1A2B3C4D-M26}). Null when either the customer
130	     * code or the registration date is absent.
131	     */
132	    default String membershipNumber(Owner owner) {
133	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
134	            return null;
135	        }
136	        return String.format("%s-M%02d", owner.getCustomerCode(),
137	                owner.getRegistrationDate().getYear() % 100);
138	    }
139	
140	    /**
141	     * The owner's membership level, a number from 1 to 4. Starts at 1; add 1 when an email is present;
142	     * add 1 when the owner's name was unique on creation (namesakeCount is 0); these pre-tenure factors
143	     * are capped at 3. Level 4 requires tenure of more than 365 days (days elapsed since the
144	     * registrationDate); because a newly created owner has zero tenure, a new owner never exceeds
145	     * level 3.
146	     */
147	    static int membershipLevel(Owner owner) {
148	        int level = 1;
149	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
150	        if (hasEmail) {
151	            level++;
152	        }
153	        Integer namesakeCount = owner.getNamesakeCount();
154	        if (namesakeCount != null && namesakeCount == 0) {
155	            level++;
156	        }
157	        level = Math.min(level, 3);
158	        if (owner.getRegistrationDate() != null
159	                && java.time.temporal.ChronoUnit.DAYS.between(
160	                        owner.getRegistrationDate(), java.time.LocalDate.now()) > 365) {
161	            level++;
162	        }
163	        return level;
164	    }
165	
166	    Owner toOwner(OwnerDto ownerDto);
167	
168	    @Mapping(target = "id", ignore = true)
169	    @Mapping(target = "pets", ignore = true)
170	    Owner toOwner(OwnerFieldsDto ownerDto);
171	
172	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
173	
174	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
175	
176	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
177	        OwnerPageDto ownerPageDto = new OwnerPageDto();
178	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
179	        ownerPageDto.setPage(ownerPage.getNumber());
180	        ownerPageDto.setSize(ownerPage.getSize());
181	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
182	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
183	        return ownerPageDto;
184	    }
185	}
