1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's deterministic {@code householdId} — the first 12 hex characters of SHA-256 over
9	 * the normalized lastName and postcode (see {@link OwnerIdentity#deriveHouseholdId}). Because the id
10	 * is a pure function of (lastName, postcode), every owner that shares a lastName and postcode resolves
11	 * to the same value automatically, with no back-filling and regardless of creation order. It also
12	 * records {@code householdSize} — the number of owners that share this household after the create
13	 * (the existing members with the same computed householdId, plus this new owner). Runs before
14	 * {@link SaveOwner}, so {@link OwnerRepository#findAll()} returns only the owners that predate this
15	 * create.
16	 */
17	public class AssignHouseholdId {
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        String householdId = OwnerIdentity.deriveHouseholdId(
21	                OwnerIdentity.normalizeName(owner.getLastName()), owner.getPostcode());
22	        owner.setHouseholdId(householdId);
23	
24	        // Count the existing members of this household (same computed householdId) plus this owner.
25	        int size = 1;
26	        for (Owner existing : ownerRepository.findAll()) {
27	            String existingHousehold = OwnerIdentity.deriveHouseholdId(
28	                    OwnerIdentity.normalizeName(existing.getLastName()), existing.getPostcode());
29	            if (householdId.equals(existingHousehold)) {
30	                size++;
31	            }
32	        }
33	        owner.setHouseholdSize(size);
34	    }
35	}
